const enforcementThemes={plexlight:{name:'Light',colors:['#f4f6fa','#ffffff','#1c2b42','#2358d5','#edf1f8','#5f6e83','#dce3ee'],dark:false},plexdark:{name:'Dark',colors:['#101722','#192332','#e5ecf5','#9cbcff','#243246','#a6b5c9','#33445a'],dark:true}};
Object.assign(paletteOptions,enforcementThemes);
let operationalTheme=localStorage.getItem('ipe-operational-theme')||'plexlight';if(!enforcementThemes[operationalTheme])operationalTheme='plexlight';
const policyApplicability={
approval:{operation:'change.execute',resource:'Production change requests',match:'Environment is production; operation executes a change.',requirement:'Two distinct maintainer approvals for the exact change.',environment:'Production',targets:['east-01','east-02','east-03']},
access:{operation:'access.elevate',resource:'Privileged access requests',match:'Request grants elevated access to a production resource.',requirement:'An approved access window that has not expired.',environment:'Production',targets:['east-01','east-02','east-03']},
window:{operation:'change.execute',resource:'Scheduled production changes',match:'Production change requests subject to a maintenance window.',requirement:'The requested execution time is within an approved window.',environment:'Production',targets:[]},
remediation:{operation:'remediation.complete',resource:'Remediation completion requests',match:'A workflow attempts to mark remediation complete.',requirement:'Fresh verification evidence for the remediation.',environment:'Production',targets:['east-01','east-02']},
build:{operation:'release.publish',resource:'Release artifacts',match:'A production release is submitted for publication.',requirement:'Build originates from the reviewed commit and an approved runner.',environment:'Production',targets:['east-01','east-02','east-03']},
bypass:{operation:'change.execute',resource:'Emergency production changes',match:'An emergency change requests an exception.',requirement:'An authorized incident commander and an unexpired exception.',environment:'Production',targets:[]}
};
function applicability(p){return policyApplicability[p.id]||{operation:'Not configured',resource:p.scope,match:'Match criteria must be configured before assignment.',requirement:'See draft rule.',environment:'Unspecified',targets:[]}}
function policyTargetTable(p){const a=applicability(p);if(!a.targets.length)return `<div class="empty">${p.status==='Paused'?'Enforcement paused.':'Not assigned.'} No active targets are shown for this revision.</div>`;return `<div class="table-wrap"><table><thead><tr><th>Enforcement endpoint</th><th>Desired</th><th>Reported active</th><th>Delivery</th></tr></thead><tbody>${a.targets.map(id=>{const waiting=p.id==='approval'&&id==='east-03'&&!assigned;return `<tr><td><button class="record-link" data-action="endpoint" data-id="${id}">${id}</button></td><td class="mono">${p.rev}</td><td class="mono">${waiting?'r16':p.rev}</td><td>${badge(waiting?'Waiting':'Applied',waiting?'warn':'good')}</td></tr>`}).join('')}</tbody></table></div>`}
function enforcementTable(limit){const rows=policies.filter(p=>{const a=applicability(p);return (!filter||p.status===filter)&&(!query||`${p.name} ${a.operation} ${a.resource} ${a.environment} ${a.targets.join(' ')}`.toLowerCase().includes(query.toLowerCase()))}).slice(0,limit||99);return `<div class="table-wrap"><table class="enforcement-table"><thead><tr><th>Policy / required condition</th><th>Applies to</th><th>Enforcement targets</th><th>Desired → active</th><th>State</th></tr></thead><tbody>${rows.map(p=>{const a=applicability(p),lag=p.id==='approval'&&!assigned;return `<tr><td><button class="record-link" data-action="policy" data-id="${p.id}">${esc(p.name)}</button><span class="sub">${esc(a.requirement)}</span></td><td><span class="mono">${a.operation}</span><span class="sub">${esc(a.resource)}</span><span class="scope-label">${a.environment}</span></td><td>${a.targets.length?`<span class="mono">${a.targets.join(', ')}</span>`:'—'}<span class="sub">${a.targets.length?`${a.targets.length} managed endpoints`:'No assignment'}</span></td><td class="mono">${a.targets.length?p.rev:'—'} → ${a.targets.length?(lag?'r17 / r16':p.rev):'—'}${lag?'<span class="sub lag">east-03 behind</span>':''}</td><td>${badge(p.status,p.status==='Active'?'good':p.status==='Draft'?'blue':'warn')}</td></tr>`}).join('')}</tbody></table>${rows.length?'':'<div class="empty">No policies match the operation, resource, or endpoint.</div>'}</div>`}
function policyDetails(p,inline=false){const a=applicability(p);return `<section class="match-summary"><h3>Enforcement scope</h3><div class="field-grid"><div><small>Operation</small><p class="mono">${a.operation}</p></div><div><small>Resource</small><p>${esc(a.resource)}</p></div><div><small>Environment</small><p>${a.environment}</p></div><div><small>Assigned endpoints</small><p>${a.targets.join(', ')||'None'}</p></div></div><p><strong>Matches when:</strong> ${a.match}</p><small class="muted">Illustrative match criteria. Matching a request and assigning a revision are separate controls.</small></section>${p.id==='approval'?policyDetailsBase(p,inline):policyDetailsBase(p,inline).replace(/<div class="detail-section"><h3>Try the approval guard example<\/h3>[\s\S]*?<div id="test-result" style="margin-top:12px"><\/div><\/div>/,'')}`}
function operationsNavigation(){const section=['contracts','integrations'].includes(current.screen)?'integrations':['map','fleet','observability'].includes(current.screen)?'observability':current.screen;return `<header class="ops-header"><a href="#workspace/overview" class="ops-brand"><i class="ops-logomark" aria-hidden="true"><b></b><b></b></i><strong>ipe</strong><span>Control plane</span></a><nav aria-label="Main navigation">${[['overview','Overview'],['policies','Policies'],['integrations','Integrations'],['observability','Telemetry'],['rollouts','Rollouts']].map(([id,label])=>`<a href="#workspace/${id}" ${section===id?'aria-current="page"':''}>${icon(({overview:'overview',policies:'policy',integrations:'integration',observability:'observe',rollouts:'rollout'})[id])}<span>${label}</span></a>`).join('')}</nav><span class="ops-environment">Northstar <span>/</span> Production</span></header>`}
function operationsSubnav(){const group=['integrations','contracts'].includes(current.screen)?[['integrations','Connections'],['contracts','External policies']]:['observability','map','fleet'].includes(current.screen)?[['observability','Signals'],['map','Service map'],['fleet','Endpoints']]:[];return group.length?`<nav class="ops-subnav" aria-label="Section navigation">${group.map(([id,label])=>`<a href="#workspace/${id}" ${current.screen===id?'aria-current="page"':''}>${label}</a>`).join('')}</nav>`:''}
function operationalOverview(){return `${head('Operational overview','Production · illustrative registry state',link('Service map','map'))}<div class="ops-metrics">${[['Enforcement current',assigned?'3 / 3':'2 / 3','policies'],['Active policies',policies.filter(p=>p.status==='Active').length,'policies'],['Integration connections','2 / 2','integrations'],['Telemetry compliant',assigned?'4 / 4':'3 / 4','observability']].map(([l,v,d])=>`<a href="#workspace/${d}"><span>${l}</span><strong>${v}</strong>${icon('arrow')}</a>`).join('')}</div><div class="ops-overview-grid"><section class="panel">${`<div class="panel-head"><h2>Policy enforcement</h2>${link('All policies','policies','quiet small')}</div>`}${enforcementTable(4)}</section><aside class="ops-attention panel"><div class="panel-head"><h2>Requires attention</h2></div>${!assigned?`<a href="#workspace/rollouts"><span class="ops-severity">Assignment</span><strong>east-03 has not applied r17</strong><small>Active r16 · last report 12 minutes ago</small>${icon('arrow')}</a>`:''}<button data-action="contract" data-id="closure"><span class="ops-severity">Source coverage</span><strong>ServiceNow closure condition is unknown</strong><small>Observed external policy has partial coverage</small>${icon('arrow')}</button>${!assigned?`<a href="#workspace/observability"><span class="ops-severity">Telemetry</span><strong>east-03 canary is missing</strong><small>New rollout blocked by telemetry profile</small>${icon('arrow')}</a>`:''}<a href="#workspace/contracts"><span class="ops-severity">Freshness</span><strong>Maintenance observation has expired</strong><small>Re-observe source before relying on it</small>${icon('arrow')}</a></aside></div><div class="ops-bottom-grid">${panel('Recent activity',feed())}${panel('Source connections',integrationSummaryTable())}</div>`}
function integrationSummaryTable(){return `<div class="table-wrap"><table><thead><tr><th>Source connection</th><th>External policies</th><th>Knowledge state</th></tr></thead><tbody><tr><td><button class="record-link" data-action="integration" data-id="servicenow">ServiceNow</button><span class="sub mono">integration-01</span></td><td>2</td><td>${badge('Partial coverage','warn')}<span class="sub">${externalRefreshes.maintenance?'Observations current':'1 expired observation'}</span></td></tr><tr><td><button class="record-link" data-action="integration" data-id="github">GitHub</button><span class="sub mono">integration-01</span></td><td>1</td><td>${badge('Current','good')}</td></tr></tbody></table></div>`}
function operationalIntegrations(){return `${head('Integrations','Source connections and the external policies they discover.',btn('Connect source','connection-guide','primary'))}${panel('Connections',integrationSummaryTable())}<div class="ops-section-label"><h2>External policies</h2>${link('All external policies','contracts','quiet small')}</div>${panel('External policy requirements',externalPolicyTable())}<div class="ops-inline-note">Integration records requirements and evaluations from each external enforcement system.</div><div class="ops-bottom-grid">${panel('Integration endpoint',`<div class="panel-body"><div class="row spread"><button class="record-link" data-action="endpoint" data-id="integration-01">integration-01</button>${badge('Connected','good')}</div><p class="muted" style="margin-top:12px">Publishes scoped external policy observations, evaluation receipts, and expiring facts.</p></div>`)}${panel('External evaluation observations',`<div class="panel-body"><button class="record-link" data-action="receipt">CHG-2041 · ServiceNow closure rejected</button><p class="muted" style="margin-top:10px">Result is bound to the recorded actor, operation, input, and time.</p></div>`)}</div>`}
function operationalPolicies(){return `${head('Policy enforcement','Request scope, assigned endpoints, and reported active revisions.',btn('New draft','new-policy',''))}<div class="ops-inline-note"><strong>${policies.filter(p=>p.status==='Active').length} active rules</strong><span>${assigned?'All assignments current':'1 endpoint behind'}</span><span>Scope determines which requests match; assignment determines where the rule runs.</span></div>${panel('Enforcement rules',toolbar('Search policy, operation, resource, or endpoint',['Active','Draft','Paused'])+enforcementTable())}`}
function operationalMap(){return `${head('Service map','Policy delivery and observed source relationships.',link('Endpoint registry','fleet'))}<div class="ops-map-status">${badge(assigned?'All current':'1 endpoint behind',assigned?'good':'warn')}<span>4 registered endpoints · 2 source connections</span><button class="btn quiet small" data-action="endpoint" data-id="integration-01">Inspect integration runtime ${icon('arrow')}</button></div><div class="ops-map">${topology()}</div>`}
function renderBoldWorkspace(){paletteSelection=operationalTheme;const content=({overview:scaleOverview,policies:scalePolicyScreen,integrations:scaleIntegrationScreen,map:scaleFleetScreen,contracts:externalPolicyScreen,fleet:scaleEndpointScreen,observability:scaleTelemetryScreen,rollouts:scaleRolloutScreen}[current.screen])();$('#app').innerHTML=`<div class="review-shell workspace ops-workspace">${operationsNavigation()}${operationsSubnav()}<main class="ops-main">${content}</main><footer class="ops-footer"><span>Sample data · 4,800 generated policies</span><div><button data-action="feedback">Feedback</button><button data-ops-theme>${operationalTheme==='plexlight'?'Dark':'Light'} mode</button><button data-scale-about>About this mock</button></div></footer></div>`;applyPalette();document.title=`${screens.find(x=>x[0]===current.screen)?.[1]} · IPE Control Plane`}
document.addEventListener('click',e=>{if(!e.target.closest('[data-ops-theme]'))return;operationalTheme=operationalTheme==='plexlight'?'plexdark':'plexlight';localStorage.setItem('ipe-operational-theme',operationalTheme);render()});
